using System;
using System.Linq;
using UnityEngine;
using UnityEditor;
public static class ValidateVehicleLayouts
{
 public static string Main(){if(!Application.isPlaying)throw new Exception("Requires Play");var source=UnityEngine.Object.FindAnyObjectByType<VehiclePhysics>().profile;var mode=Physics.simulationMode;bool paused=EditorApplication.isPaused;var floor=new GameObject("TEMP generic layouts floor");floor.transform.position=new Vector3(20000,20,20000);var box=floor.AddComponent<BoxCollider>();box.size=new Vector3(300,1,300);box.center=Vector3.down*.5f;string report="";
 try{Physics.simulationMode=SimulationMode.Script;EditorApplication.isPaused=true;foreach(int type in new[]{0,1,2}){var root=new GameObject("TEMP independent vehicle "+type);var p=UnityEngine.Object.Instantiate(source);try{p.massKg=type==2?5000:1400;p.axles=new VehicleAxleSettings[type==2?3:2];for(int a=0;a<p.axles.Length;a++)p.axles[a]=new VehicleAxleSettings{name="Configured axle "+a,steering=a==0,handbrake=a>0,primaryDrive=type==0?a==0:a>0,driveShare=type==0?(a==0?1:0):type==1?(a==1?1:0):(a>0?.5f:0),antiRollN=4000};var hull=root.AddComponent<BoxCollider>();hull.center=new Vector3(0,1,0);hull.size=new Vector3(1.7f,1.2f,4.5f);if(type==2)foreach(var axle in p.axles){axle.springNPerMetre=100000;axle.damperNsPerMetre=12000;axle.suspensionTravel=.3f;}root.transform.position=new Vector3(20000,20.6f,20000);var physics=root.AddComponent<VehiclePhysics>();physics.automaticSimulation=false;physics.externalControl=true;physics.profile=p;physics.axles=new VehicleAxleBinding[p.axles.Length];for(int a=0;a<p.axles.Length;a++){var binding=new VehicleAxleBinding();for(int side=0;side<2;side++){var go=new GameObject("Wheel "+a+" "+side);go.transform.SetParent(root.transform,false);go.transform.localPosition=new Vector3(side==0?-.78f:.78f,.39731f,a==0?1.5f:a==1?-1.2f:-2.3f);var w=go.AddComponent<WheelCollider>();if(side==0)binding.left=w;else binding.right=w;}var leftHub=new GameObject("Left visual "+a).transform;leftHub.SetParent(root.transform,false);leftHub.position=binding.left.transform.position;binding.leftVisual=leftHub;var rightHub=new GameObject("Right visual "+a).transform;rightHub.SetParent(root.transform,false);rightHub.position=binding.right.transform.position;binding.rightVisual=rightHub;physics.axles[a]=binding;}physics.Initialize();if(!physics.Ready||root.GetComponent<ForestKamazController>()!=null)throw new Exception("Shared core requires branded controller");var chains=root.AddComponent<TruckChains>();root.AddComponent<VehicleWinch>();physics.Initialize();if(chains.wheelChainVisuals==null||chains.wheelChainVisuals.Length!=physics.Wheels.Length||chains.wheelChainVisuals.Any(x=>x==null))throw new Exception("Generic chain visuals missing");physics.SetInput(new VehicleControlInput{brake=1});for(int i=0;i<200;i++){physics.Simulate(.01f);Physics.Simulate(.01f);}physics.SetTransmission(false,type==2);physics.SetInput(new VehicleControlInput{throttle=1});float torque=0;for(int i=0;i<500;i++){physics.Simulate(.01f);Physics.Simulate(.01f);foreach(var w in physics.Wheels)torque=Mathf.Max(torque,Mathf.Abs(w.motorTorque));}if(root.transform.position.y<19||physics.Wheels.Count(w=>w.isGrounded)<2||physics.SpeedKmh<3||torque<10)throw new Exception("Layout does not drive: "+type);for(int a=0;a<p.axles.Length;a++)if(p.axles[a].driveShare==0&&(Mathf.Abs(physics.Wheels[a*2].motorTorque)>.01f||Mathf.Abs(physics.Wheels[a*2+1].motorTorque)>.01f))throw new Exception("Torque on undriven axle");report+=(type==0?"FWD / 4 wheels":type==1?"RWD / 4 wheels":"two driven rear axles / 6 wheels")+"="+physics.SpeedKmh.ToString("F1")+"km/h; ";}finally{UnityEngine.Object.DestroyImmediate(root);UnityEngine.Object.DestroyImmediate(p);}}return "PASS independent shared-core layouts, profile clones and axle configuration; no branded controllers added. "+report;}finally{UnityEngine.Object.DestroyImmediate(floor);Physics.simulationMode=mode;EditorApplication.isPaused=paused;}
 }
}

